package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.networknt.schema.*;import com.ruoyi.medical.contracts.*;import java.util.*;import java.io.IOException;
public final class FormalEvaluationScoreBindingSchema {
 private final FormalAgentPublicationSchema json;private final JsonSchema schema;private final com.fasterxml.jackson.databind.json.JsonMapper reader=com.fasterxml.jackson.databind.json.JsonMapper.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS,com.fasterxml.jackson.databind.DeserializationFeature.USE_BIG_INTEGER_FOR_INTS,com.fasterxml.jackson.databind.DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS).build();
 public FormalEvaluationScoreBindingSchema(FormalAgentPublicationSchema json)throws IOException{this.json=json;try(var in=Objects.requireNonNull(getClass().getResourceAsStream("/formal-evaluation-score-binding.schema.json"))){schema=JsonSchemaFactory.getInstance(SpecVersion.VersionFlag.V202012).getSchema(json.read(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8)),SchemaValidatorsConfig.builder().formatAssertionsEnabled(true).build());}}
 public JsonNode request(byte[] bytes)throws IOException{if(bytes==null||bytes.length==0||bytes.length>FormalAgentPublicationSchema.MAXIMUM_BYTES)throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);return validate(reader.readTree(bytes));}
 public JsonNode recovery(byte[] bytes)throws IOException{if(bytes==null||bytes.length==0||bytes.length>2*FormalAgentPublicationSchema.MAXIMUM_BYTES)throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);var node=definition("FormalRecovery",reader.readTree(bytes));validate(node.required("request"));return node;}
 public JsonNode receipt(JsonNode node){return definition("FormalReceipt",node);}
 private JsonNode definition(String name,JsonNode node){if(node==null||!schema.getSubSchema(new JsonNodePath(PathType.JSON_POINTER).append("$defs").append(name)).validate(node).isEmpty())throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);return node;}
 public JsonNode validate(JsonNode value)throws IOException{if(value==null||!schema.getSubSchema(new JsonNodePath(PathType.JSON_POINTER).append("$defs").append("FormalScoreBinding")).validate(value).isEmpty()||json.canonical(value).getBytes(java.nio.charset.StandardCharsets.UTF_8).length>FormalAgentPublicationSchema.MAXIMUM_BYTES)throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);var binding=value.required("binding");if(!value.path("evaluation").path("version_id").asText().equals(binding.path("evaluation_id").asText())||!value.path("evaluation").path("content_sha256").asText().equals(binding.path("definition_sha256").asText()))throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);return value;}
}
